    private Facts facts(){String c=id(),d=id(),p=id(),p2=id(),e=id(),j=id();jdbc.update("INSERT INTO company(id,code,name,created_at) VALUES(?,?,'Import company',UTC_TIMESTAMP(6))",c,c);jdbc.update("INSERT INTO department(id,company_id,code,name,created_at) VALUES(?,?,?,'Import department',UTC_TIMESTAMP(6))",d,c,d);for(String pos:List.of(p,p2))jdbc.update("INSERT INTO `position`(id,department_id,code,name,created_at) VALUES(?,?,?,'Import position',UTC_TIMESTAMP(6))",pos,d,pos);jdbc.update("INSERT INTO employee(id,employee_key,name,created_at) VALUES(?,?,'Before',UTC_TIMESTAMP(6))",e,e);jdbc.update("INSERT INTO employment(id,employee_id,company_id,department_id,position_id,created_at) VALUES(?,?,?,?,?,UTC_TIMESTAMP(6))",j,e,c,d,p);return new Facts(c,d,p,p2,e,j);}
    private String ready(String csv,String...fields)throws Exception{String b=batch(input("PERSONNEL_CHANGES",file(csv),fields));assertThat(body(get("/"+b)).path("state").stringValue()).as(body(get("/"+b)).toString()).isEqualTo("READY");return b;}
    private JsonNode success(String b)throws Exception{var r=commit(b,commitInput(b),id());assertThat(r.statusCode()).as(r.body()).isEqualTo(200);return body(r);}
    private String[] grant(Facts f){String sys=id(),role=id(),source=id(),baseline=id(),request=id(),grant=id();jdbc.update("INSERT INTO business_system(id,code,name,created_at) VALUES(?,?,'Import system',UTC_TIMESTAMP(6))",sys,sys);jdbc.update("INSERT INTO business_role(id,code,name,company_id,department_id,system_id,state,configuration_version,created_at) VALUES(?,?,'Import role',?,?,?,'EFFECTIVE',1,UTC_TIMESTAMP(6))",role,role,f.company(),f.department(),sys);jdbc.update("INSERT INTO authorization_source(id,employee_id,company_id,department_id,system_id) VALUES(?,?,?,?,?)",source,f.employee(),f.company(),f.department(),sys);jdbc.update("INSERT INTO grant_baseline(id,source_id,role_id,company_id,system_id,relation_version) VALUES(?,?,?,?,?,1)",baseline,source,role,f.company(),sys);jdbc.update("INSERT INTO change_request(id,kind,company_id,content,reason,created_at) VALUES(?,'ROLE_GRANT',?,'{}','Persisted grant history fixture',UTC_TIMESTAMP(6))",request,f.company());jdbc.update("INSERT INTO role_grant(id,baseline_id,relation_version,source_epoch,granted_by_request_id,created_at) VALUES(?,?,1,0,?,UTC_TIMESTAMP(6))",grant,baseline,request);jdbc.update("INSERT INTO grant_employment_evidence(grant_id,employment_id) VALUES(?,?)",grant,f.job());return new String[]{source,baseline,grant,role,sys};}
    private String appoint(Facts f)throws Exception{String a=id(),scope=id();jdbc.update("INSERT INTO admin_account(id,employee_id,login_name,password_hash,must_change_password,created_at) VALUES(?,?,?,?,0,UTC_TIMESTAMP(6))",a,f.employee(),a,new PasswordPolicy().encode("Precheck-Fixture-123456"));jdbc.update("INSERT INTO management_scope(id,company_id,department_id,created_at) VALUES(?,?,?,UTC_TIMESTAMP(6))",scope,f.company(),f.department());jdbc.update("INSERT INTO admin_appointment(id,scope_id,account_id,created_at) VALUES(?,?,?,UTC_TIMESTAMP(6))",id(),scope,a);login(a);return a;}
    @Test void initializesFrozenEmployeeAndEmploymentAndNewBatchIsUnchanged()throws Exception{
        var f=facts();String key=id();var in=input("EMPLOYEE_INITIALIZATION",file("employeeKey,name,companyCode,departmentCode,positionCode\n"+key+",New employee,"+f.company()+","+f.department()+","+f.position()+"\n"),"employeeKey","name","companyCode","departmentCode","positionCode");long accounts=count("admin_account"),grants=count("role_grant");String b=batch(in);var done=success(b);assertThat(done.path("actualCounts").path("created").longValue()).isEqualTo(2);String e=jdbc.queryForObject("SELECT id FROM employee WHERE employee_key=?",String.class,key);assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM employment WHERE employee_id=?",Long.class,e)).isEqualTo(1);assertThat(count("admin_account")).isEqualTo(accounts);assertThat(count("role_grant")).isEqualTo(grants);
        in.put("sourceBatchId",id());var again=success(batch(in));assertThat(again.path("actualCounts").path("created").longValue()).isZero();assertThat(again.path("actualCounts").path("unchanged").longValue()).isEqualTo(1);
    }
