    @Test void finalSuccessAuditFailureRollsBackEverythingAndFreshKeyCanRetryFrozenPlan()throws Exception{
        String b=batch(organization());long companies=count("company"),events=count("audit_event");db.execute("CREATE TRIGGER be30_audit_fail BEFORE INSERT ON audit_event FOR EACH ROW BEGIN IF NEW.event_type='IMPORT_COMMITTED' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='fixture'; END IF; END");
        try{var r=commit(b,commitInput(b),id());assertThat(r.statusCode()).as(r.body()).isEqualTo(503);}finally{db.execute("DROP TRIGGER be30_audit_fail");}
        assertThat(count("company")).isEqualTo(companies);assertThat(count("audit_event")).isEqualTo(events+1);var failed=body(get("/"+b));assertThat(failed.path("state").stringValue()).isEqualTo("FAILED");assertThat(failed.path("actualCounts").isNull()).isTrue();var done=success(b);assertThat(done.path("state").stringValue()).isEqualTo("SUCCEEDED");assertThat(done.path("version").longValue()).isEqualTo(3);
    }
    @Test void concurrentDifferentKeysCommitOneBatchAndReturnOneStoredResult()throws Exception{
        String b=batch(organization());var input=commitInput(b);var pool=Executors.newFixedThreadPool(2);var start=new CountDownLatch(1);
        try{var one=pool.submit(()->{start.await();return commit(b,input,id());});var two=pool.submit(()->{start.await();return commit(b,input,id());});start.countDown();var a=one.get(30,TimeUnit.SECONDS);var c=two.get(30,TimeUnit.SECONDS);assertThat(a.statusCode()).as(a.body()).isEqualTo(200);assertThat(c.statusCode()).as(c.body()).isEqualTo(200);assertThat(body(a)).isEqualTo(body(c));assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM audit_event WHERE event_type='IMPORT_COMMITTED' AND target_id=?",Long.class,b)).isEqualTo(1);}finally{pool.shutdownNow();assertThat(pool.awaitTermination(10,TimeUnit.SECONDS)).isTrue();}
    }
