    @Test void auditFailureAfterLifecycleRollsBackEmployeeSourcesGrantsClaimsAndSessions()throws Exception{
        var f=facts();var g=grant(f);String a=appoint(f),request=pendingRevocation(g);String b=ready("action,employeeId,expectedVersion\nDISABLE_EMPLOYEE,"+f.employee()+",1\n","action","employeeId","expectedVersion");db.execute("CREATE TRIGGER be30_lifecycle_fail BEFORE INSERT ON audit_event FOR EACH ROW BEGIN IF NEW.event_type='IMPORT_COMMITTED' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='fixture'; END IF; END");try{assertThat(commit(b,commitInput(b),id()).statusCode()).isEqualTo(503);}finally{db.execute("DROP TRIGGER be30_lifecycle_fail");}assertThat(jdbc.queryForObject("SELECT status FROM employee WHERE id=?",String.class,f.employee())).isEqualTo("ACTIVE");assertThat(jdbc.queryForObject("SELECT source_epoch FROM authorization_source WHERE id=?",Long.class,g[0])).isZero();assertThat(jdbc.queryForObject("SELECT status FROM role_grant WHERE id=?",String.class,g[2])).isEqualTo("ACTIVE");assertThat(jdbc.queryForObject("SELECT state FROM change_request WHERE id=?",String.class,request)).isEqualTo("PENDING");assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM relation_change_claim WHERE request_id=?",Long.class,request)).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM admin_session WHERE account_id=? AND revoked_at IS NULL",Long.class,a)).isEqualTo(1);success(b);
    }
