        commands.execute(()->new com.adgn.backend.core.transaction.CommandBoundary.Identity<>(new com.adgn.backend.people.EmploymentWriter.ImportAuthority(UUID.fromString(account),UUID.fromString(b),((Number)input.get("expectedVersion")).longValue(),(String)input.get("contentDigest"),"Delayed failure",id()),new com.adgn.backend.core.audit.AuditRecord.Actor(com.adgn.backend.core.audit.AuditRecord.ActorKind.ACCOUNT,account)),c->{type.getMethod("record",com.adgn.backend.core.transaction.WriteContext.class,String.class).invoke(recorder,c,"FAILED");return null;});assertThat(body(get("/"+b))).isEqualTo(result);assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM audit_event WHERE target_id=? AND event_type='IMPORT_FAILED'",Long.class,b)).isZero();
